try { currentLang = localStorage.getItem('nasiRasulLang') || currentLang; } catch(e){}

function applyLang(){
  document.querySelectorAll('.lang-opt').forEach(el => el.classList.toggle('active', el.dataset.lang===currentLang));
  document.documentElement.lang = currentLang;
  for(const key in t){
    const el = document.getElementById(key);
    if(!el) continue;
    if(key === 'heroTitle'){ el.innerHTML = t[key][currentLang]; }
    else { el.textContent = t[key][currentLang]; }
  }
  document.querySelectorAll('[data-i18n]').forEach(el => {
    const k = el.dataset.i18n;
    if(t[k]) el.textContent = t[k][currentLang];
  });
  const ml = document.getElementById('methodList');
  if(ml) ml.innerHTML = methodList[currentLang].map(li => `<li>${li}</li>`).join('');
  const grid = document.getElementById('catalogGrid');
  if(grid) renderCatalog(document.querySelector('.filter-btn.active')?.dataset.filter || 'all');
  if(document.getElementById('glossaryGrid')) renderGlossary();
}

const catSlug = c => c.toLowerCase().replace(/\s+/g,'-');

function renderCatalog(filter){
  const grid = document.getElementById('catalogGrid');
  if(!grid) return;
  grid.innerHTML = '';
  catalog.filter(item => filter==='all' || item.category===filter).forEach(item => {
    const card = document.createElement('div');
    card.className = `card cat-${catSlug(item.category)}`;
    const title = currentLang==='en' ? item.title_en : item.title;
    const desc = currentLang==='en' ? item.desc_en : item.desc;
    const catLabel = currentLang==='en' ? item.category_en : item.category;
    card.innerHTML = `
      <div class="card-swatch" style="${photos[item.code] ? `background-image:linear-gradient(180deg, rgba(36,26,18,0) 45%, rgba(36,26,18,0.65) 100%), url('${photos[item.code]}'); background-size:cover; background-position:center;` : ''}">
        <span class="card-code">${item.code}</span>
        <span class="card-tag">${catLabel}</span>
      </div>
      <div class="card-body">
        <h3>${title}</h3>
        <p class="desc">${desc}</p>
        <span class="card-open">${t.cardOpen[currentLang]}</span>
      </div>`;
    card.addEventListener('click', () => openModal(item));
    grid.appendChild(card);
  });
}

function openModal(item){
  const modal = document.getElementById('modalContent');
  if(!modal) return;
  const lang = currentLang;
  const title = lang==='en' ? item.title_en : item.title;
  const desc = lang==='en' ? item.desc_en : item.desc;
  const catLabel = lang==='en' ? item.category_en : item.category;
  const makna = lang==='en' ? item.makna_en : item.makna;
  const etika = lang==='en' ? item.etika_en : item.etika;
  let extraHtml = '';
  if(item.extra && item.extra.length){
    extraHtml = item.extra.map(e => {
      const em = lang==='en' ? e.makna_en : e.makna;
      return `<div class="record-value extra">"${em}" (${e.informan})</div>`;
    }).join('');
  }
  modal.innerHTML = `
    <button class="modal-close" id="modalClose">✕</button>
    ${photos[item.code] ? `<img src="${photos[item.code]}" alt="${item.code}" style="width:100%;max-height:340px;object-fit:cover;border-radius:18px 18px 0 0;">` : ''}
    <div class="modal-head">
      <span class="card-code mono">${item.code} · ${catLabel}</span>
      <h3>${title}</h3>
    </div>
    <div class="record-grid">
      <div class="record-row">
        <div class="record-label">${t.recDeskripsi[lang]}</div>
        <div class="record-value">${desc}</div>
      </div>
      <div class="record-row">
        <div class="record-label">${t.recTarikh[lang]}</div>
        <div class="record-value">${item.tarikh} · ${item.lokasi}</div>
      </div>
      <div class="record-row">
        <div class="record-label">${t.recMakna[lang]}</div>
        <div class="record-value">${makna}</div>
        ${extraHtml}
      </div>
      <div class="record-row">
        <div class="record-label">${t.recInforman[lang]}</div>
        <div class="record-value">${item.informan}</div>
      </div>
      <div class="record-row">
        <div class="record-label">${t.recEtika[lang]}</div>
        <div class="record-value">${etika}</div>
      </div>
    </div>`;
  document.getElementById('modalBackdrop').classList.add('open');
  document.getElementById('modalClose').addEventListener('click', closeModal);
}

function closeModal(){
  const b = document.getElementById('modalBackdrop');
  if(b) b.classList.remove('open');
}

const backdrop = document.getElementById('modalBackdrop');
if(backdrop){
  backdrop.addEventListener('click', e => { if(e.target.id==='modalBackdrop') closeModal(); });
}
document.addEventListener('keydown', e => { if(e.key==='Escape') closeModal(); });

const filterBar = document.getElementById('filterBar');
if(filterBar){
  filterBar.addEventListener('click', e => {
    if(!e.target.classList.contains('filter-btn')) return;
    document.querySelectorAll('.filter-btn').forEach(b=>b.classList.remove('active'));
    e.target.classList.add('active');
    renderCatalog(e.target.dataset.filter);
  });
}

function renderGlossary(){
  const grid = document.getElementById('glossaryGrid');
  if(!grid) return;
  const lang = currentLang;
  grid.innerHTML = glossary.map(g => `
    <div class="gloss-card">
      <div class="g-symbol">${lang==='en' ? g.symbol_en : g.symbol}</div>
      <p>${lang==='en' ? g.desc_en : g.desc}</p>
      <div class="g-source">${t.glosariSource[lang]} ${g.source}</div>
    </div>`).join('');
}

const langToggle = document.getElementById('langToggle');
if(langToggle){
  langToggle.addEventListener('click', () => {
    currentLang = currentLang === 'ms' ? 'en' : 'ms';
    try { localStorage.setItem('nasiRasulLang', currentLang); } catch(e){}
    applyLang();
  });
}

(function markActiveNav(){
  const page = document.body.dataset.page;
  if(!page) return;
  document.querySelectorAll('.nav-links a').forEach(a => {
    a.classList.toggle('active', a.dataset.page===page);
  });
})();

applyLang();

const visitEl = document.getElementById('visitCount');
if(visitEl && typeof fetch === 'function'){
  fetch('https://nasi-rasul.goatcounter.com/counter/TOTAL.json')
    .then(r => r.json())
    .then(d => { if(d && d.count != null) visitEl.textContent = d.count; })
    .catch(() => {});
}
